fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    // For each element in y, we create a row in X by cloning x,
    // and a row in Y by repeating that y value nx times.
    let xx = y.iter()
              .map(|_| x.clone())
              .collect::<Vec<Vec<f32>>>();
    let yy = y.iter()
              .map(|&yi| vec![yi; nx])
              .collect::<Vec<Vec<f32>>>();
    (xx, yy)
}

